export function payloadOf(doc){const {_cloud,...payload}=doc;return payload;}
export function markSynced(payload,revision){return {...payload,_cloud:{revision,base:JSON.stringify(payload)}};}
export function mergeSessions(local,remote){const sessions=local.map(s=>structuredClone(s)),conflicts=[];for(const row of remote){const i=sessions.findIndex(s=>s.id===row.id);if(i<0){sessions.push(markSynced(row.payload,row.revision));continue;}const item=sessions[i],json=JSON.stringify(payloadOf(item));if(json===JSON.stringify(row.payload)){sessions[i]=markSynced(row.payload,row.revision);continue;}if(item._cloud?.revision===row.revision)continue;if(item._cloud?.base===json){sessions[i]=markSynced(row.payload,row.revision);}else conflicts.push(row.id);}return {sessions,conflicts};}
export function sessionForEdit(sessions,id){const session=sessions.find(s=>s.id===id);if(!session)throw new Error('Caminhada não encontrada. Reabra o histórico.');return session;}
export function editFingerprint(s){return JSON.stringify({pace:s.pace??'',correctedMinutes:s.correctedMinutes??null,correctionOriginalActive:s.correctionOriginalActive??null,manualKm:s.manualKm??null,treadmill:s.treadmill??[],efforts:s.efforts??[],stairs:s.stairs??[],notes:s.notes??'',profileSnapshot:s.profileSnapshot??null});}
